SELECT t."MONTH", t."REGION", t."SALES_TARGET", t."MARGIN_TARGET", a."REVENUE", a."GROSS_PROFIT", a."REVENUE"-t."SALES_TARGET" AS "REVENUE_VARIANCE"
FROM "TARGETS" t LEFT JOIN (SELECT "MONTH", "REGION", SUM("REVENUE") AS "REVENUE", SUM("GROSS_PROFIT") AS "GROSS_PROFIT" FROM "V_MONTHLY" GROUP BY "MONTH", "REGION") a ON t."MONTH"=a."MONTH" AND t."REGION"=a."REGION"
